customMethods.script:

# Dagre-like layered layout (horizontal by default: Left -> Right)
# Returns a LIST of nodes with `position` assigned
# Ignition Perspective / Jython 2.7 compatible

direction="LR"
nodeWidth=180
nodeHeight=60
rankSep=160
nodeSep=60
sweeps=6
marginX=20
marginY=20
alignLanes=True
minRankSpacing=None
avoidEdgeOverlap=True
edgePadding=18
maxEdgeResolveIters=12

isVertical = direction in ("TB", "BT")
reverseRanks = direction in ("BT", "RL")

if minRankSpacing is None:
	minRankSpacing = nodeHeight + nodeSep

# ----------------------------
# Helpers
# ----------------------------
def clamp(value, lo, hi):
	if value < lo: 	return lo
	if value > hi: 	return hi
	return value

def rectsIntersect(a, b):
	# a,b: (l,t,r,b)
	return not (a[2] <= b[0] or a[0] >= b[2] or a[3] <= b[1] or a[1] >= b[3])

def nodeRect(pos):
	# pos is top-left
	x = float(pos["x"])
	y = float(pos["y"])
	return (x, y, x + float(nodeWidth), y + float(nodeHeight))

def segCorridorRect(x1, y1, x2, y2, pad):
	# axis-aligned segment only (we only generate H/V segments)
	l = min(x1, x2) - pad
	r = max(x1, x2) + pad
	t = min(y1, y2) - pad
	b = max(y1, y2) + pad
	return (l, t, r, b)

# Union-Find (Disjoint Set)
def ufMake(idSet):
	parent = {}
	size = {}
	for nodeId in idSet:
		parent[nodeId] = nodeId
		size[nodeId] = 1
	return parent, size

def ufFind(parent, a):
	while parent[a] != a:
		parent[a] = parent[parent[a]]
		a = parent[a]
	return a

def ufUnion(parent, size, a, b):
	ra = ufFind(parent, a)
	rb = ufFind(parent, b)
	if ra == rb: return
	if size[ra] < size[rb]:
		ra, rb = rb, ra
	parent[rb] = ra
	size[ra] = size[ra] + size[rb]

# Build lookup
ids = []
idSet = set()

for node in nodes:
	nodeId = node.get("id")
	if nodeId is not None:
		ids.append(nodeId)
		idSet.add(nodeId)

outMap = {}
inMap = {}

for nodeId in ids:
	outMap[nodeId] = []
	inMap[nodeId] = []

for edge in edges:
	source = edge.get("source")
	target = edge.get("target")
	if source in idSet and target in idSet:
		outMap[source].append(target)
		inMap[target].append(source)

outDegree = {}
inDegree = {}
maxConnect = 0
for nodeId in ids:
	outDegree[nodeId] = len(outMap.get(nodeId, []))
	inDegree[nodeId] = len(inMap.get(nodeId, []))
	if max(outDegree[nodeId], inDegree[nodeId]) > maxConnect: maxConnect = max(outDegree[nodeId], inDegree[nodeId])

# This is where we detect that the trace is just one singular line
self.view.custom.traceDisplayOptions.edgeType = 'smoothstep' if maxConnect == 1 else 'bezier'
if maxConnect == 1:

	# Find source node
	source = None
	for searchNode in inMap:
		if len(inMap[searchNode]) == 0: 
			source = searchNode
			break

	if source is not None:
		nodePositionMap = {}
		screenWidth = self.page.props.dimensions.viewport.width
		rowLength = max(4, screenWidth / 340)
		counter = 0
		maxLimit = 30
		currentNode = source
		while currentNode and counter < 100:
			nodePositionMap[currentNode] = {'x': 20 + (counter % (rowLength - 1)) * 340, 'y': 20 + (counter / (rowLength - 1)) * 150}
			currentNode = outMap[currentNode][0] if len(outMap[currentNode]) else None
			counter += 1

		formattedNodes = []
		for node in nodes:
			nodeCopy = dict(node)
			nodeCopy['position'] = nodePositionMap[node['id']]
			formattedNodes.append(nodeCopy)

		return formattedNodes

# Rank assignment (DFS)
rank = {}
visiting = set()
visited = set()

def dfs(nodeId):
	if nodeId in rank: 	return rank[nodeId]
	if nodeId in visiting: return 0	# cycle break
	if nodeId in visited: return rank.get(nodeId, 0)

	visiting.add(nodeId)
	best = 0

	for nextId in outMap.get(nodeId, []):
		dist = 1 + dfs(nextId)
		if dist > best:
			best = dist

	visiting.remove(nodeId)
	visited.add(nodeId)
	rank[nodeId] = best
	return best

maxRank = 0
for nodeId in ids:
	rv = dfs(nodeId)
	if rv > maxRank: maxRank = rv

# Invert so sources start at rank 0
for nodeId in ids: 	rank[nodeId] = maxRank - rank.get(nodeId, 0)

if reverseRanks:
	for nodeId in ids: 	rank[nodeId] = maxRank - rank.get(nodeId, 0)

# Build layers
layers = []
for _ in range(maxRank + 1): layers.append([])

for nodeId in ids:
	rv = clamp(rank.get(nodeId, 0), 0, maxRank)
	layers[rv].append(nodeId)

orderIndex = {}
for r in range(len(layers)):
	layers[r].sort()
	for i, nodeId in enumerate(layers[r]):
		orderIndex[nodeId] = i

# Crossing reduction (barycenter)
def barycenterSort(layerIds, neighborLayer):
	def neighbors(nodeId):
		if neighborLayer == "prev": return inMap.get(nodeId, [])
		return outMap.get(nodeId, [])

	scored = []
	for nodeId in layerIds:
		nbs = neighbors(nodeId)
		if not nbs:
			key = 10 ** 18
		else:
			total = 0.0
			for nb in nbs: 	total += float(orderIndex.get(nb, 0))
			key = total / float(len(nbs))

		scored.append((key, orderIndex.get(nodeId, 0), nodeId))

	scored.sort()

	for i, item in enumerate(scored):
		nodeId = item[2]
		layerIds[i] = nodeId
		orderIndex[nodeId] = i

for _ in range(int(sweeps)):
	for r in range(1, len(layers)): barycenterSort(layers[r], "prev")
	for r in range(len(layers) - 2, -1, -1): barycenterSort(layers[r], "next")

# Coordinate assignment
layerBreadths = []
for layer in layers:
	count = len(layer)
	if count <= 0: 	layerBreadths.append(0)
	else:
		perNode = nodeWidth if isVertical else nodeHeight
		layerBreadths.append(count * perNode + (count - 1) * nodeSep)

maxBreadth = 0
for breadth in layerBreadths:
	if breadth > maxBreadth: maxBreadth = breadth

positions = {}
for r in range(len(layers)):
	layer = layers[r]
	breadth = layerBreadths[r]
	startBreadth = (marginX + (maxBreadth - breadth) / 2.0) if isVertical else (marginY + (maxBreadth - breadth) / 2.0)

	for i, nodeId in enumerate(layer):
		alongLayer = startBreadth + i * ((nodeWidth if isVertical else nodeHeight) + nodeSep)
		alongRanks = (marginY + r * ((nodeHeight if isVertical else nodeWidth) + rankSep)) if isVertical else (marginX + r * ((nodeHeight if isVertical else nodeWidth) + rankSep))

		x = alongLayer if isVertical else alongRanks
		y = alongRanks if isVertical else alongLayer

		positions[nodeId] = {"x": float(x), "y": float(y)}

# Lane alignment + anti-bunching inside each rank
if alignLanes and (direction in ("LR", "RL")):
	parent, size = ufMake(idSet)

	for edge in edges:
		source = edge.get("source")
		target = edge.get("target")
		if source in idSet and target in idSet:
			if outDegree.get(source, 0) == 1 and inDegree.get(target, 0) == 1: ufUnion(parent, size, source, target)

	groupSumY = {}
	groupCount = {}
	for nodeId in ids:
		root = ufFind(parent, nodeId)
		y = positions.get(nodeId, {}).get("y", 0.0)
		groupSumY[root] = groupSumY.get(root, 0.0) + float(y)
		groupCount[root] = groupCount[root] + 1 if root in groupCount else 1

	groupAvgY = {}
	for root in groupSumY: 	groupAvgY[root] = groupSumY[root] / float(groupCount[root])

	for nodeId in ids:
		root = ufFind(parent, nodeId)
		positions[nodeId]["y"] = float(groupAvgY[root])

	for r in range(len(layers)):
		col = layers[r]
		colSorted = []
		for nodeId in col: 	colSorted.append((positions[nodeId]["y"], nodeId))
		colSorted.sort()

		if not colSorted: continue

		prevY = colSorted[0][0]
		for i in range(1, len(colSorted)):
			y, nodeId = colSorted[i]
			minY = float(prevY) + float(minRankSpacing)
			if y < minY:
				y = minY
				positions[nodeId]["y"] = float(y)
			prevY = y

# Edge overlap avoidance (approx SmoothStep corridors)
if avoidEdgeOverlap and (direction in ("LR", "RL")):

	def edgeCorridors(edge):
		source = edge.get("source")
		target = edge.get("target")
		if source not in idSet or target not in idSet: return None

		ps = positions.get(source)
		pt = positions.get(target)
		if ps is None or pt is None: return None

		# Node centers on left/right side (SmoothStep-ish)
		x1 = float(ps["x"]) + float(nodeWidth)
		y1 = float(ps["y"]) + float(nodeHeight) / 2.0
		x2 = float(pt["x"])
		y2 = float(pt["y"]) + float(nodeHeight) / 2.0

		# Midpoint X for the elbow
		mx = (x1 + x2) / 2.0

		# 3 axis-aligned segments: (x1,y1)->(mx,y1)->(mx,y2)->(x2,y2)
		pad = float(edgePadding)
		return [
			segCorridorRect(x1, y1, mx, y1, pad),
			segCorridorRect(mx, y1, mx, y2, pad),
			segCorridorRect(mx, y2, x2, y2, pad),
		], source, target

	# Prebuild list of edge corridors each iteration (depends on node positions)
	def nodeHitsAnyCorridor(nodeId, nodeR):
		for e in edges:
			res = edgeCorridors(e)
			if res is None: continue
			corrs, sId, tId = res
			if nodeId == sId or nodeId == tId: continue
			for c in corrs:
				if rectsIntersect(nodeR, c): return True
		return False

	# Push node down, and keep min spacing within its rank column
	def pushDownInRank(nodeId, deltaY):
		r = clamp(rank.get(nodeId, 0), 0, maxRank)
		positions[nodeId]["y"] = float(positions[nodeId]["y"]) + float(deltaY)

		# Enforce spacing in that rank after moving
		col = layers[r]
		colSorted = []
		for nid in col: colSorted.append((positions[nid]["y"], nid))
		colSorted.sort()

		prevY = None
		for y, nid in colSorted:
			if prevY is None:
				prevY = y
				continue
			minY = float(prevY) + float(minRankSpacing)
			if y < minY:
				positions[nid]["y"] = float(minY)
				prevY = float(minY)
			else:
				prevY = y

	# Iteratively resolve collisions
	for _ in range(int(maxEdgeResolveIters)):
		anyMoved = False

		# Check nodes in rank order for stability
		for r in range(len(layers)):
			for nodeId in layers[r]:
				nr = nodeRect(positions[nodeId])
				if nodeHitsAnyCorridor(nodeId, nr):
					# Push down one step and re-check next iteration
					pushDownInRank(nodeId, float(minRankSpacing))
					anyMoved = True

		if not anyMoved: break

# Return nodes with positions assigned
laidOutNodes = []
for node in nodes:
	nodeId = node.get("id")
	pos = positions.get(nodeId, {"x": 0.0, "y": 0.0})

	newNode = {}
	for key in node: newNode[key] = node[key]

	newNode["position"] = {"x": pos["x"], "y": pos["y"]}
	laidOutNodes.append(newNode)

return laidOutNodes

traceInfo = self.view.custom.traceInfo.click
userId = self.view.custom.security.userId

if traceInfo['lotOperationEventId']: retVal, msg = system.kanoa.lot.deleteLotOperationEvent(traceInfo['lotOperationEventId'], userId)
elif traceInfo['lotEventId']: retVal, msg = system.kanoa.lot.deleteLotEvent(traceInfo['lotEventId'], userId)
else: msg = "No trace element selected"

if msg: system.perspective.sendMessage('showFailerToast', {'message': msg})
else: 
	system.perspective.sendMessage('showSuccessfulToast', {'message': 'Trace element has been removed'})
	self.view.custom.traceInfo.click = {"lotEventId": None,  "lotId": None,  "lotOperationEventId": None}

self.view.refreshBinding("custom.lotEvents")

return

